{
  "recommendations": [
    {
      "rec_id": "r1",
      "rationale": [
        {
          "text": "NIR diffuse reflection probes are suited to scattering media, including powders.",
          "claim_type": "AFS",
          "evidence_ids": ["TABLE-nir_diffuse_reflection_probe"]
        },
        {
          "text": "In-line API concentration monitoring has been reported in the feed frame of a rotary tablet press.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p14-blend-potency"]
        }
      ],
      "conditions": [],
      "limitations": [
        {
          "text": "Overlapping NIR bands mean quantitative analysis requires chemometric calibration models.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p10-nir-chemometrics"]
        }
      ]
    },
    {
      "rec_id": "r2",
      "rationale": [
        {
          "text": "A published pharmaceutical set-up used a Raman contact probe with an excitation wavelength of 785 nm.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p15-raman-785"]
        }
      ],
      "conditions": [],
      "limitations": [
        {
          "text": "Fluorescence background can overwhelm Raman signals from many organic compounds.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p11-raman-fluorescence"]
        },
        {
          "text": "The weak Raman effect requires specialised probes.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p05-raman-weak"]
        }
      ]
    },
    {
      "rec_id": "r3",
      "rationale": [
        {
          "text": "NIR and Raman provide complementary chemical information.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p15-nir-raman-complementary"]
        },
        {
          "text": "Compare the methods separately on retained samples before choosing a method or testing their combination.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "conditions": [
        {
          "text": "For a combined test, use same-spot, time-aligned measurements with dedicated processing of the fused data.",
          "claim_type": "PROPOSAL",
          "evidence_ids": []
        }
      ],
      "limitations": [
        {
          "text": "Whether combining the methods improves performance for the new formulation is unknown.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    }
  ],
  "premise_checks": [
    {
      "premise_id": "p0",
      "explanation": [
        {
          "text": "The existing NIR calibration's validity for the new API and excipient blend is unverified.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    },
    {
      "premise_id": "p1",
      "explanation": [
        {
          "text": "The claim that adding Raman would preserve the old calibration's validity is unverified.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    }
  ],
  "direct_answer": [
    {
      "text": "Make the first experiment a check of the existing NIR calibration's predictions against reference values for the new formulation before deciding on reuse.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ],
  "verdict": "CONDITIONAL"
}
